import fs, { type FileRef } from "@rcompat/fs";
import cli from "@rcompat/cli";
import is from "@rcompat/is";
import runtime from "@rcompat/runtime";
import { Command } from "@powerups/program";
import use_errors from "#errors/useErrors";
import { instructionsSchema } from "#schemas/instruction";
import { extractVariables } from "#utils/variables";
import { checkOutput } from "#utils/check-output";
import { executeSteps } from "#utils/execute-steps";
import { logRun } from "#utils/metrics";
import {
  verifyGitRepo,
  createWorktree,
  removeWorktree,
  copyChangedFiles,
  type ChangedFile,
} from "#utils/worktree";
import { applyDependencies, collectDependencies } from "#utils/dependencies";
import { resolvePowerUp } from "#utils/resolve-powerup";
import {
  CAPITALIZED_SINGLULAR_CLI_NAME,
  MAIN_FOLDER,
  SINGULAR_NAME,
  type PowerUpType,
} from "#constants";

const EXCLUDE_FLAGS = [
  "--dry-run",
  "-d",
  "--overwrite",
  "-O",
  "--help",
  "-h",
  "--type",
  "-t",
];

const use = new Command({
  name: "use",

  description: `Use a ${SINGULAR_NAME}, rendering templates with variables`,

  flags: [
    {
      name: "type",
      long: "type",
      short: "t",
      description: `${CAPITALIZED_SINGLULAR_CLI_NAME} type (multi-use or single-use) for disambiguation`,
    },
    {
      name: "dry-run",
      long: "dry-run",
      short: "d",
      description: "Print output to stdout instead of writing files",
    },
    {
      name: "overwrite",
      long: "overwrite",
      short: "O",
      description: "Overwrite existing destination files for create actions",
    },
  ],

  subcommands: [],

  action: async ({ subcommands, rawFlags, flags, context }) => {
    // 1. Extract name from positional args
    const name = subcommands?.[0];
    if (!is.defined(name)) {
      throw use_errors.missing_name();
    }

    // 2. Locate .<CLI_NAME> folder
    const root: FileRef = context?.root ?? await runtime.projectRoot();
    const mainFolder = root.append(`/${MAIN_FOLDER}`);
    const hasMainFolder = await fs.exists(mainFolder);

    if (!hasMainFolder) {
      throw use_errors.main_folder_not_found();
    }

    // 3. Resolve powerup via resolvePowerUp (searches both folders)
    const typeFlag = is.defined(flags.type)
      ? (flags.type as PowerUpType)
      : undefined;
    const resolved = await resolvePowerUp(root, name, typeFlag);
    const outputFolder = resolved.folder;
    const typeFolder = resolved.folder.up(1);

    // 4. Validate (checkOutput)
    const issues = await checkOutput({
      rootOutputDir: typeFolder,
      currentOutputDir: outputFolder,
    });

    if (issues.length > 0) {
      throw use_errors.invalid_composition(issues);
    }

    // 5. Load & parse instructions (safe — validated)
    const outputPath = outputFolder.append("/instructions.json");
    const instructions = instructionsSchema.parse(await outputPath.json());

    // 6. Extract & validate variables
    const variables = extractVariables({
      rawFlags: rawFlags ?? [],
      required: instructions.variables.required,
      optional: instructions.variables.optional ?? [],
      excludeFlags: EXCLUDE_FLAGS,
      onMissing: (missing) => {
        throw use_errors.missing_variables(missing, instructions.variables.required, name);
      },
    });

    // 7. Detect --dry-run and --overwrite via rawFlags
    const isDryRun = (rawFlags ?? []).some(
      rawFlag => rawFlag.flag === "--dry-run" || rawFlag.flag === "-d",
    );
    const isOverwrite = (rawFlags ?? []).some(
      f => f.flag === "--overwrite" || f.flag === "-O",
    );

    // 8. Dry-run: execute steps printing to stdout
    if (is.truthy(isDryRun)) {
      await executeSteps({
        steps: instructions.steps,
        variables,
        outputFolder,
        rootDir: root,
        worktreeRoot: undefined,
        outputsFolder: typeFolder,
        isDryRun: true,
        isOverwrite,
        changedFiles: [],
      });

      // Process packageDependencies in dry-run mode
      if (instructions.packageDependencies || instructions.steps.some(s => s.type === "include")) {
        const collectedDeps = await collectDependencies({ outputName: name, outputsFolder: typeFolder });

        if (collectedDeps.length > 0) {
          await applyDependencies({
            projectRoot: root,
            packageDependencies: collectedDeps,
            isDryRun: true,
          });
        }
      }

      return;
    }

    // 9. Non-dry-run: use git worktree
    try {
      await verifyGitRepo(root);
    } catch {
      throw use_errors.git_repo_required();
    }

    const worktree = await createWorktree(root);
    const changedFiles: ChangedFile[] = [];

    let totalCharacters = 0;

    try {
      totalCharacters = await executeSteps({
        steps: instructions.steps,
        variables,
        outputFolder,
        rootDir: root,
        worktreeRoot: worktree.root,
        outputsFolder: typeFolder,
        isDryRun: false,
        isOverwrite,
        changedFiles,
      });
    } catch (error) {
      await removeWorktree(root, worktree.path);
      throw error;
    }

    // 10. Copy changed files back and clean up
    await copyChangedFiles(root, changedFiles);
    await removeWorktree(root, worktree.path);

    // 11. Process packageDependencies
    if (instructions.packageDependencies || instructions.steps.some(s => s.type === "include")) {
      try {
        const collectedDeps = await collectDependencies({ outputName: name, outputsFolder: typeFolder });

        if (collectedDeps.length > 0) {
          await applyDependencies({
            projectRoot: root,
            packageDependencies: collectedDeps,
            isDryRun: false,
          });
        }
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);

        cli.print(`Warning: dependency installation failed — ${message}\n`);
      }
    }

    // 12. Log metrics (best-effort)
    try {
      await logRun({ output: name, characters: totalCharacters }, root);
    } catch {
      // Metrics are secondary — never crash a successful run
    }
  },
});

export default use;

import test from "@rcompat/test";
import fs, { type FileRef } from "@rcompat/fs";
import runtime from "@rcompat/runtime";
import use from "#commands/use/index";
import create from "#commands/create/index";
import captureStdout from "#test-utils/capture-stdout";
import { CodeError } from "@rcompat/error";
import { UseErrorCode } from "#errors/useErrors";
import { exec } from "node:child_process";
import { promisify } from "node:util";
import { tmpdir } from "node:os";
import { randomBytes } from "node:crypto";
import path from "node:path";
import { readMetrics } from "#utils/metrics";
import {
  MAIN_FOLDER,
  INTERNAL_FOLDER,
  SRC_FOLDER,
  ACTIVE_FOLDER,
  MULTI_USE_FOLDER,
  SINGLE_USE_FOLDER,
  PACKAGE_FILE,
  KEYWORD_PACKAGE,
  CONFIG_FILE,
} from "#constants";

const execAsync = promisify(exec);

const root = await runtime.projectRoot();
const testRoot: FileRef = root.append("/tmp");
const mainFolder: FileRef = testRoot.append(`/${MAIN_FOLDER}`);
const internalFolder: FileRef = mainFolder.append(`/${INTERNAL_FOLDER}`);
const multiUseFolder: FileRef = internalFolder.append(`/test-pkg/${SRC_FOLDER}/${ACTIVE_FOLDER}/${MULTI_USE_FOLDER}`);

const createCmd = create;

async function gitInit(dir: FileRef): Promise<void> {
  await execAsync("git init", { cwd: dir.path });
  await execAsync("git config user.email test@test.com", { cwd: dir.path });
  await execAsync("git config user.name test", { cwd: dir.path });
  await dir.append("/README.md").write("init");
  await execAsync("git add -A", { cwd: dir.path });
  await execAsync("git commit -m init", { cwd: dir.path });
}

async function gitCommit(dir: FileRef, message: string): Promise<void> {
  await execAsync("git add -A", { cwd: dir.path });
  try {
    await execAsync(`git commit -m "${message}"`, { cwd: dir.path });
  } catch {
    // Nothing to commit — that's fine
  }
}

/**
 * Create a powerup with the given steps and optional packageDependencies.
 * Uses createCmd.run to scaffold the folder, then overwrites instructions.json
 * with the provided steps format.
 */
async function createPowerup(name: string, steps: unknown[], packageDependencies?: unknown) {
  await createCmd.run({
    subcommands: [],
    flags: [
      { flag: "--pack", value: "test-pkg" },
      { flag: "--type", value: "multi-use" },
      { flag: "--name", value: name },
      { flag: "--description", value: "test description" },
    ],
    context: { root: testRoot },
  });
  await multiUseFolder.append(`/${name}/instructions.json`).writeJSON({
    name,
    description: "test description",
    variables: { required: [] },
    intent: [],
    ...(packageDependencies ? { packageDependencies } : {}),
    steps,
  } as never);
}

async function reset() {
  await testRoot.remove();
  await fs.create(testRoot);
  await fs.create(mainFolder);
  await fs.create(internalFolder);
  // Create test package
  const pkgDir = internalFolder.append("/test-pkg");
  const srcActive = pkgDir.append(`/${SRC_FOLDER}/${ACTIVE_FOLDER}`);
  await fs.create(srcActive.append(`/${MULTI_USE_FOLDER}`));
  await fs.create(srcActive.append(`/${SINGLE_USE_FOLDER}`));
  await pkgDir.append(`/${PACKAGE_FILE}`).writeJSON({
    name: "test-pkg",
    version: "1.0.0",
    description: "test",
    keywords: [KEYWORD_PACKAGE],
    powerups: { active: { [MULTI_USE_FOLDER]: {}, [SINGLE_USE_FOLDER]: {} } },
  });
  // Create config with test-pkg listed
  await mainFolder.append(`/${CONFIG_FILE}`).writeJSON({
    harness: "claude",
    packages: ["test-pkg"],
  });
  await gitInit(testRoot);
}

